import {getClientVersion} from '@github-ui/client-version'
import {isFeatureEnabled} from '@github-ui/feature-flags'

import {versionMismatchRateLimiter} from './rate-limiter'

export interface MismatchDetails {
  clientVersion: string
  serverVersion?: string
  requestUrl: string
  responseHeaders: Headers
  appName?: string
}

export type VersionMismatchHandler = (details: MismatchDetails) => void

export interface VersionMismatchConfig {
  onMismatchDetected: VersionMismatchHandler
}

class VersionMismatchDetector {
  #appConfigs = new Map<string, VersionMismatchConfig>()

  registerApp(appName: string, config: VersionMismatchConfig): void {
    this.#appConfigs.set(appName, config)
  }

  unregisterApp(appName: string): void {
    this.#appConfigs.delete(appName)
  }

  checkResponse(response: Response, appName?: string): boolean {
    const versionMismatch = response.headers.get('X-GitHub-Version-Mismatch')
    if (versionMismatch !== 'true') {
      return false
    }

    if (!isFeatureEnabled('react_version_mismatch_detection')) {
      return false
    }

    if (!versionMismatchRateLimiter.canTrigger()) {
      return false
    }

    const clientVersion = getClientVersion()
    const details: MismatchDetails = {
      clientVersion,
      serverVersion: response.headers.get('X-GitHub-Server-Version') || undefined,
      requestUrl: response.url,
      responseHeaders: response.headers,
      appName,
    }

    versionMismatchRateLimiter.recordTrigger()

    if (appName) {
      const config = this.#appConfigs.get(appName)
      if (config) {
        config.onMismatchDetected(details)
        return true
      }
    } else {
      let handled = false
      for (const [registeredAppName, config] of this.#appConfigs.entries()) {
        const appDetails = {...details, appName: registeredAppName}
        config.onMismatchDetected(appDetails)
        handled = true
      }
      return handled
    }

    return false
  }
}

export const versionMismatchDetector = new VersionMismatchDetector()
