import {ControlGroup} from '@github-ui/control-group'
import {ClaimCustomizationSection} from './ClaimCustomizationSection'
import {MultiSelectPropertiesPicker} from './properties-picker/MultiSelectPropertiesPicker'
import type {CustomPropertyInclusionsPayload, CustomPropertyItem, SettingsSource} from '../types'
import {useState} from 'react'
import {useOIDCConfigurationMutation} from '../hooks/use-oidc-configuration-mutation'
import {useBannerContext} from '../context/BannerProvider'
import {useConfigurationSource} from '../hooks/use-configuration-source'
import {getEnterpriseCustomPropertiesPath, getOrganizationCustomPropertiesPath} from '../paths'
import {Button, Link} from '@primer/react'
import {isFeatureEnabled} from '@github-ui/feature-flags'

const CUSTOM_PROPERTIES_CONFIG = {
  enterprise: {
    getSettingsPath: (name: string) => getEnterpriseCustomPropertiesPath({business: name}),
    docsPath:
      'https://docs.github.com/en/enterprise-cloud@latest/admin/managing-accounts-and-repositories/managing-organizations-in-your-enterprise/custom-properties',
  },
  organization: {
    getSettingsPath: (name: string) => getOrganizationCustomPropertiesPath({org: name}),
    docsPath:
      'https://docs.github.com/en/organizations/managing-organization-settings/managing-custom-properties-for-repositories-in-your-organization',
  },
} as const

type Props = {
  includedProperties?: CustomPropertyItem[]
  propertyCount?: number
  source?: SettingsSource
}

export function CustomPropertyInclusions({
  includedProperties: initialIncludedProperties,
  propertyCount,
  source,
}: Props) {
  const {settingsLevel, sourceName} = useConfigurationSource()
  const [includedProperties, setIncludedProperties] = useState(initialIncludedProperties ?? [])
  const {setBanner} = useBannerContext()
  const showCallToAction = isFeatureEnabled('actions_oidc_custom_property_cta')

  const {isPending: isSaving, mutate: saveCustomPropertyClaims} =
    useOIDCConfigurationMutation<CustomPropertyInclusionsPayload>({
      pathSuffix: 'custom-property-claims',
      onSuccess: () => {
        setBanner({message: 'Custom property claims configuration saved successfully.', type: 'success'})
      },
    })

  // Managing custom property inclusions is not supported at the repository level
  if (settingsLevel === 'repository') return null

  const {getSettingsPath, docsPath} = CUSTOM_PROPERTIES_CONFIG[settingsLevel]
  const showPropertiesPicker = !showCallToAction || propertyCount !== 0

  return (
    <ClaimCustomizationSection
      className="tmp-p-3"
      title="Custom property claims"
      subtitle="Specify which custom properties should be included as claims in the OIDC token."
      onSave={() => {
        const includedPropertyNames = includedProperties.map(property => property.propertyName)
        saveCustomPropertyClaims({includedProperties: includedPropertyNames})
      }}
      isSaving={isSaving}
      showSaveButton={showPropertiesPicker}
    >
      {!showPropertiesPicker ? (
        <CustomPropertiesCallToAction settingsPath={getSettingsPath(sourceName)} docsPath={docsPath} />
      ) : (
        <CustomPropertiesPickerSection
          includedProperties={includedProperties}
          source={source}
          setIncludedProperties={setIncludedProperties}
        />
      )}
    </ClaimCustomizationSection>
  )
}

function CustomPropertiesPickerSection({
  includedProperties,
  source,
  setIncludedProperties,
}: {
  includedProperties: CustomPropertyItem[]
  source?: SettingsSource
  setIncludedProperties: (properties: CustomPropertyItem[]) => void
}) {
  return (
    <ControlGroup.Item>
      <ControlGroup.Title className="fgColor-default">Select custom properties for inclusion</ControlGroup.Title>
      <ControlGroup.Description id="custom-property-inclusions">
        Manage the included custom properties.
      </ControlGroup.Description>
      <ControlGroup.Custom>
        <MultiSelectPropertiesPicker
          selected={includedProperties}
          onSubmit={setIncludedProperties}
          aria-describedby="custom-property-inclusions"
          source={source}
        />
      </ControlGroup.Custom>
    </ControlGroup.Item>
  )
}

function CustomPropertiesCallToAction({settingsPath, docsPath}: {settingsPath: string; docsPath: string}) {
  return (
    <ControlGroup.Item>
      <ControlGroup.Title className="fgColor-default">No custom properties defined</ControlGroup.Title>
      <ControlGroup.Description>
        Define custom properties to include them as claims in OIDC tokens.{' '}
        <Link href={docsPath} target="_blank" rel="noopener" inline>
          Learn more about repository custom properties.
        </Link>
      </ControlGroup.Description>
      <ControlGroup.Custom>
        <Button as="a" href={settingsPath} variant="primary">
          Manage custom properties
        </Button>
      </ControlGroup.Custom>
    </ControlGroup.Item>
  )
}
