import type {ItemConfig} from '@github-ui/filter-picker'
import type {PickerProperty} from './types'
import type {SettingsLevel, SettingsSource} from '../../types'
import {
  getEnterpriseOidcConfigurationPath,
  getSearchEnterpriseCustomPropertiesPath,
  getSearchOrganizationCustomPropertiesPath,
} from '../../paths'
import {useConfigurationSource} from '../../hooks/use-configuration-source'
import {Link, Truncate} from '@primer/react'
import {ShieldLockIcon} from '@primer/octicons-react'
import styles from './ItemConfig.module.css'

const literals = {
  itemName: 'custom property',
  itemsName: 'custom properties',
  listTitle: 'Custom properties list',
}

export function usePropertyItemConfig(source?: SettingsSource): ItemConfig<PickerProperty> {
  const {settingsLevel, sourceName} = useConfigurationSource()

  if (settingsLevel !== 'organization' && settingsLevel !== 'enterprise') {
    throw new Error(`Unexpected settings level for property inclusion configuration: ${settingsLevel}`)
  }

  const baseConfig: ItemConfig<PickerProperty> = {
    literals,
    getSearchUrl: query => `${searchPath(settingsLevel, sourceName)}?q=${encodeURIComponent(query)}`,
    onRenderItemName: property => property.propertyName,
    isHollow: () => false,
  }

  if (settingsLevel === 'enterprise') return baseConfig
  return {
    ...baseConfig,
    onRenderItemDisabled: property => isEnterpriseManaged(settingsLevel, property.inclusionSource),
    onRenderItemTrailingVisual: property => {
      if (isEnterpriseManaged(settingsLevel, property.inclusionSource) && source) {
        return (
          <div className={styles.trailingVisual}>
            <ShieldLockIcon size="small" />
            <span>Opted in by</span>
            <Truncate title={source.name} maxWidth="15ch" inline>
              {source.name}
            </Truncate>
          </div>
        )
      }
      return null
    },
    onRenderFooterDetails: () => {
      if (source) {
        return (
          <span className={styles.footerDetails}>
            Properties included at the enterprise level cannot be modified here.{' '}
            <Link href={getEnterpriseOidcConfigurationPath({business: source.slug})} inline>
              Manage these inclusions in the enterprise settings.
            </Link>
          </span>
        )
      }
      return null
    },
  }
}

const searchPath = (settingsLevel: SettingsLevel, sourceName: string) => {
  switch (settingsLevel) {
    case 'enterprise':
      return getSearchEnterpriseCustomPropertiesPath({business: sourceName})
    case 'organization':
      return getSearchOrganizationCustomPropertiesPath({org: sourceName})
    default:
      throw new Error(`Unexpected settings level for property inclusion configuration: ${settingsLevel}`)
  }
}

const isEnterpriseManaged = (settingsLevel: SettingsLevel, propertyInclusionSource?: SettingsLevel) => {
  return settingsLevel === 'organization' && propertyInclusionSource === 'enterprise'
}
