import {SelectPickerDialog} from '@github-ui/filter-picker'
import {usePropertyItemConfig} from './ItemConfig'
import type {MultiSelectPropertiesDialogProps, PickerProperty} from './types'
import type {SelectFilterProvider} from '@github-ui/filter-core/providers'
import {PropertyTypeFilterProvider, RequiredFilterProvider} from '@github-ui/custom-properties-core/filter-providers'

export function MultiSelectPropertiesPickerDialog<TItem extends PickerProperty>(
  props: MultiSelectPropertiesDialogProps<TItem>,
) {
  const {selected, source, ...restProps} = props

  const {onRenderFooterDetails, ...itemConfig} = usePropertyItemConfig(source)
  const sortedSelected = selected
    ? [...selected].sort((a, b) => a.propertyName.localeCompare(b.propertyName))
    : undefined

  return (
    <SelectPickerDialog<TItem>
      {...restProps}
      title="Select custom properties"
      selectionVariant="multiple"
      providers={getDefaultPropertiesProviders()}
      itemConfig={itemConfig}
      selected={sortedSelected}
      onRenderFooterDetails={onRenderFooterDetails}
    />
  )
}

function getDefaultPropertiesProviders(): SelectFilterProvider[] {
  return [new PropertyTypeFilterProvider(), new RequiredFilterProvider()]
}
